CREATE TABLE feedback_sprint_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sprint_key text NOT NULL, session_token text NOT NULL, source text, scenario text, rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), clarity integer NOT NULL CHECK (clarity BETWEEN 1 AND 5), trust integer NOT NULL CHECK (trust BETWEEN 1 AND 5), usefulness integer NOT NULL CHECK (usefulness BETWEEN 1 AND 5), comment text, created_at timestamptz NOT NULL DEFAULT now());